// Official University of Lakki Marwat (ULM 2017) Authentic Crest
// Single Source of Truth for:
// 1. Desktop App Icon & Window Favicon
// 2. Official App Brand Logo (Header, Welcome Modal, Reports)
// 3. Student / Faculty CR80 Library ID Card Logo & Card Watermark
// 4. Full-Application Background Watermark

export const ULM_OFFICIAL_CREST_ASSET_PATH = "/assets/aistudio/863417491_2133473440593759_7550028921333764276_n_01e05516.png";
export const ULM_OFFICIAL_CREST_SRC = "data:image/png;base64,";

/**
 * Dynamically updates the browser/Electron window icon, Apple touch icon,
 * and shortcut icon so the authentic ULM 2017 Crest is always the Desktop Icon.
 */
export function syncAppDesktopAndFaviconIcon(logoSrc: string = ULM_OFFICIAL_CREST_SRC): void {
  if (typeof document === "undefined") return;

  const rels = ["icon", "shortcut icon", "apple-touch-icon"];
  rels.forEach((rel) => {
    let link = document.querySelector(`link[rel="${rel}"]`) as HTMLLinkElement | null;
    if (!link) {
      link = document.createElement("link");
      link.rel = rel;
      document.head.appendChild(link);
    }
    link.type = "image/png";
    link.href = logoSrc;
  });

  document.title = "ULM Central Library Management System — University of Lakki Marwat";

  try {
    const anyWin = window as unknown as {
      electronAPI?: { setAppIcon?: (src: string) => void };
    };
    if (anyWin.electronAPI?.setAppIcon) {
      anyWin.electronAPI.setAppIcon(logoSrc);
    }
  } catch {
    // Safe fallback in browser mode
  }
}

export default ULM_OFFICIAL_CREST_SRC;
